import './style.css';
import { createExploration } from './exploration.js';
import './game-hud.css';
import { rebuildOcean } from './ocean-environment.js';
import { createAnimatedDiver } from './animated-diver.js';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';

const STORAGE_KEY = 'scuba-explorer-save';
const DEFAULT_SAVE = {
  saveVersion: 1,
  spendablePoints: 0,
  lifetimePoints: 0,
  ownedEquipment: ['starter_tank', 'starter_suit', 'starter_fins'],
  equipped: { tank: 'starter_tank', suit: 'starter_suit', fins: 'starter_fins', light: null },
  completedMaps: [],
  bestDepthByMap: {},
  settings: { soundEnabled: true, reducedMotion: false }
};

const equipment = {
  starter_tank: { slot: 'tank', name: 'Starter tank', price: 0, detail: '100 oxygen units', capacity: 100 },
  improved_tank: { slot: 'tank', name: 'Improved tank', price: 600, detail: '140 oxygen units', capacity: 140 },
  advanced_tank: { slot: 'tank', name: 'Advanced tank', price: 1200, detail: '180 oxygen units', capacity: 180 },
  starter_suit: { slot: 'suit', name: 'Starter suit', price: 0, detail: 'Standard protection', fatigueFactor: 1 },
  reinforced_suit: { slot: 'suit', name: 'Reinforced suit', price: 700, detail: '20% less collision damage', fatigueFactor: 1 },
  exploration_suit: { slot: 'suit', name: 'Exploration suit', price: 1400, detail: '15% less fatigue', fatigueFactor: .85 },
  starter_fins: { slot: 'fins', name: 'Starter fins', price: 0, detail: 'Standard swimming effort' },
  efficient_fins: { slot: 'fins', name: 'Efficient fins', price: 500, detail: '10% less swimming effort', effortFactor: .9 },
  dive_light: { slot: 'light', name: 'Dive light', price: 400, detail: 'Improves visibility in dark maps' }
};

const maps = [
  { id: 1, name: 'Open Ocean', depth: '2–12M', objective: 'Recover three training markers', reward: 250, color: 'lagoon' },
  { id: 2, name: 'Coral Reef', depth: '4–28M', objective: 'Document three species and retrieve a sensor', reward: 400, color: 'reef', requirement: 'Complete Training Lagoon' },
  { id: 3, name: 'Sunken Wreck', depth: '8–42M', objective: 'Recover the research log', reward: 600, color: 'wreck', requirement: 'Complete Coral Reef + Improved Tank' },
  { id: 4, name: 'Deep Research Zone', depth: '12–60M', objective: 'Repair two sensor stations', reward: 800, color: 'deep', requirement: 'Complete Sunken Wreck + Advanced Tank + Dive Light' }
];

function cloneDefault() { return JSON.parse(JSON.stringify(DEFAULT_SAVE)); }
function loadSave() {
  try {
    const raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
    if (!raw || typeof raw !== 'object') return cloneDefault();
    const save = cloneDefault();
    if ('points' in raw) { save.spendablePoints = Number(raw.points) || 0; save.lifetimePoints = Number(raw.lifetime) || 0; save.equipped.tank = raw.tank || 'starter_tank'; save.equipped.suit = raw.suit || 'starter_suit'; save.completedMaps = Array.isArray(raw.completed) ? raw.completed : []; }
    else Object.assign(save, raw, { equipped: { ...save.equipped, ...(raw.equipped || {}) }, settings: { ...save.settings, ...(raw.settings || {}) } });
    save.spendablePoints = Math.max(0, Number(save.spendablePoints) || 0);
    save.lifetimePoints = Math.max(0, Number(save.lifetimePoints) || 0);
    save.ownedEquipment = Array.from(new Set(Array.isArray(save.ownedEquipment) ? save.ownedEquipment.filter(id => equipment[id]) : cloneDefault().ownedEquipment));
    save.completedMaps = Array.from(new Set(Array.isArray(save.completedMaps) ? save.completedMaps.filter(id => maps.some(m => m.id === id)) : []));
    for (const slot of ['tank', 'suit', 'fins', 'light']) if (save.equipped[slot] && !equipment[save.equipped[slot]]) save.equipped[slot] = slot === 'light' ? null : DEFAULT_SAVE.equipped[slot];
    return save;
  } catch { return cloneDefault(); }
}
function persist() { localStorage.setItem(STORAGE_KEY, JSON.stringify(save)); }
function bankDiscovery(points) { state.explorationPoints=(state.explorationPoints||0)+points;save.spendablePoints+=points;save.lifetimePoints+=points;persist(); }
function isUnlocked(map) { return map.id === 1; }
function equipped(slot) { return equipment[save.equipped[slot]] || equipment[DEFAULT_SAVE.equipped[slot]]; }
function oxygenPercent() { return Math.round(clamp(state.oxygen, 0, 100)); }
function clamp(value, min, max) { return Math.max(min, Math.min(max, value)); }

const save = loadSave();
let state = { screen: 'menu', modal: null, toast: '', running: false, paused: false, mapId: 1, oxygen: 100, stamina: 100, fatigue: 0, health: 100, heart: 76, depth: 4, provisional: 0, markers: 0, time: 0, keys: {}, last: 0, sprintLocked: false, checkpoints: new Set(), result: null };
let scene3d = null;

function icon(name) { const paths = { compass: 'M12 2 8.5 8.5 2 12l6.5 3.5L12 22l3.5-6.5L22 12l-6.5-3.5L12 2Z', check: 'm5 12 4 4L19 6', lock: 'M6 10h12v10H6zM8 10V7a4 4 0 0 1 8 0v3' }; return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.compass}"/></svg>`; }
function brand() { return `<a class="brand" href="#" data-action="home" aria-label="Scuba Explorer home"><span class="brand-icon">${icon('compass')}</span><span><b>SCUBA</b><small>EXPLORER</small></span></a>`; }
function topbar(showBack = false) { return `<header class="topbar">${showBack ? '<button class="icon-btn" data-action="back" aria-label="Back to dock">←</button>' : ''}${brand()}<div class="top-actions"><span class="wallet"><span class="wallet-dot">✦</span><strong>${Math.floor(save.spendablePoints).toLocaleString()}</strong> pts</span>${showBack ? '<button class="ghost-btn" data-action="home">MAIN MENU</button>' : ''}</div></header>`; }

function menu() { return `<main class="menu-screen"><div class="menu-glow"></div><section class="menu-content">${brand()}<p class="kicker">FIELD OPERATIONS / 01</p><h1>Go deeper.<br><em>Come back wiser.</em></h1><p class="menu-copy">An underwater exploration prototype about calm decisions, limited resources, and the route home.</p><div class="menu-actions"><button class="primary-btn" data-action="continue">CONTINUE TO DOCK <span>→</span></button><button class="secondary-btn" data-action="new-game">NEW EXPEDITION</button><button class="secondary-btn" data-action="settings">SETTINGS</button><button class="secondary-btn" data-action="how-to">HOW TO PLAY</button></div><div class="menu-meta"><span>${save.completedMaps.length}/3 training milestones complete</span><span>LOCAL SAVE · OFFLINE READY</span></div></section><div class="menu-art" aria-label="Stylized underwater scene"><div class="surface-line"></div><div class="sun-disc"></div><div class="ray ray-a"></div><div class="ray ray-b"></div><div class="dive-silhouette"><i></i><b></b><span></span></div><div class="art-fish fish-a"></div><div class="art-fish fish-b"></div><div class="art-coral coral-a"></div><div class="art-coral coral-b"></div><div class="art-coral coral-c"></div></div>${overlay()}</main>`; }
function mapCard(map) { const unlocked = isUnlocked(map); return `<button class="map-card ${map.color} ${unlocked ? '' : 'locked'}" ${unlocked ? `data-map="${map.id}"` : 'disabled'}><span class="map-number">0${map.id}</span><span class="map-symbol">${unlocked ? '◌' : icon('lock')}</span><strong>${map.name}</strong><small>${map.depth} · ${unlocked ? map.objective : 'Under development'}</small><i>${unlocked ? 'SELECT ZONE →' : 'UNDER DEVELOPMENT'}</i></button>`; }
function dock() { const selected = maps.find(m => m.id === state.mapId) || maps[0]; return `<main class="app-shell">${topbar()}<section class="dock-hero"><div class="dock-intro"><p class="kicker">DIVE PREPARATION · ${String(selected.id).padStart(2, '0')}</p><h1>Read the water.<br><em>Respect the limits.</em></h1><p>Prepare your route, check your equipment, and return to the buoy with the objective complete.</p><button class="primary-btn" data-action="start">BEGIN ${selected.name.toUpperCase()} <span>→</span></button></div><div class="hero-window"><div class="window-label">LIVE CONDITIONS <span>CALM</span></div><div class="hero-grid"></div><div class="hero-diver"></div><div class="hero-marker">✦</div><div class="hero-seabed"></div><div class="hero-kelp"></div></div></section><section class="dock-layout"><div class="panel map-panel"><div class="section-head"><div><p class="kicker">SELECT A SITE</p><h2>Dive zones</h2></div><span class="progress-chip">1/4 available</span></div><div class="maps">${maps.map(mapCard).join('')}</div></div><div class="panel loadout-panel"><div class="section-head"><div><p class="kicker">YOUR LOADOUT</p><h2>Equipment</h2></div><button class="text-btn" data-action="open-shop">SHOP →</button></div>${loadoutRow('tank', 'Tank')} ${loadoutRow('suit', 'Suit')} ${loadoutRow('fins', 'Fins')}${save.equipped.light ? loadoutRow('light', 'Light') : '<div class="empty-slot"><span>+</span><div><strong>Optional dive light</strong><small>Unlocks darker zones</small></div><button class="text-btn" data-action="open-shop">ADD</button></div>'}</div></section><footer class="footer"><span>SCUBA EXPLORER · SCHOOL PROJECT BUILD</span><span>WASD / ARROWS SWIM · SHIFT SPRINT · E INTERACT · ESC PAUSE</span></footer>${overlay()}</main>`; }
function loadoutRow(slot, label) { const item = equipped(slot); return `<div class="loadout-row"><span class="loadout-icon">${slot === 'tank' ? '◉' : slot === 'suit' ? '◇' : slot === 'fins' ? '≈' : '▣'}</span><div><span class="row-label">${label}</span><strong>${item.name}</strong><small>${item.detail}</small></div><span class="equipped-badge">EQUIPPED</span></div>`; }

function statRow(id, label, value, tone, suffix = '%') { return `<div class="stat-row"><div><span>${label}</span><b id="${id}-value">${Math.round(value)}${suffix}</b></div><div class="meter"><i id="${id}-bar" class="${tone}" style="width:${clamp(value, 0, 100)}%"></i></div></div>`; }
function dive() { const map = maps.find(m => m.id === state.mapId) || maps[0]; return `<main class="dive-screen arcade-dive"><div class="water-world"><canvas id="scene" aria-label="Underwater training lagoon"></canvas><div class="water-vignette"></div><div class="direction-marker" id="direction-marker">↑ <span>BUOY</span></div><div class="interaction-hint" id="interaction-hint">E TO INTERACT</div></div><div class="arcade-hud"><div class="arcade-top"><div class="arcade-left"><button class="round-control" data-action="toggle-pause" aria-label="Pause dive"><svg viewBox="0 0 24 24"><path d="M7 5v14M17 5v14"/></svg></button><button class="round-control" data-action="camera" aria-label="Camera view"><svg viewBox="0 0 24 24"><path d="M4 8h3l2-2h6l2 2h3v11H4zM12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/></svg></button></div><div class="oxygen-display"><span class="tank-icon">◉</span><div class="oxygen-track"><i id="oxygen-bar" style="width:${oxygenPercent()}%"></i></div><b id="oxygen-value">${oxygenPercent()}%</b></div><button class="round-control exit-control" data-action="abort" aria-label="Abort dive">×</button></div><div class="mission-chip"><span class="mode-dot"></span><strong>${map.name.toUpperCase()}</strong><span id="marker-count">${state.markers}/3</span><span id="depth-count">${Math.round(state.depth)}M</span></div><div class="resource-strip"><span>STAMINA <b id="stamina-value">${Math.round(state.stamina)}%</b></span><span>HEALTH <b id="health-value">${Math.round(state.health)}%</b></span><span>HEART <b id="heart-value">${Math.round(state.heart)} BPM</b></span><span id="oxygen-warning" class="warning"></span></div><div class="arcade-controls"><button class="round-control move-control" data-move="up" aria-label="Swim up">▲</button><button class="round-control action-control" data-move="swim" aria-label="Swim forward"><span>≈</span></button><button class="round-control move-control" data-move="down" aria-label="Swim down">▼</button></div><div class="free-mode">FREE MODE</div><div class="arcade-help">WASD / ARROWS · SHIFT SPRINT · E COLLECT</div><div class="toast" id="toast" aria-live="polite">${state.toast}</div>${state.paused ? pauseOverlay() : ''}${overlay()}</div></main>`; }
function pauseOverlay() { return `<div class="pause-overlay" role="dialog" aria-modal="true" aria-label="Paused"><div class="pause-card"><h2>Dive paused</h2><p>Collected: <strong>${state.explorationPoints || 0} points</strong></p><p>Saved wallet: ${save.spendablePoints} points. Resources are frozen while paused.</p><button class="primary-btn" data-action="resume">RESUME</button><button class="secondary-btn" data-action="confirm-abort">RETURN TO DOCK</button></div></div>`; }
function results() { const r = state.result || { success: false, markers: 0, depth: 0, points: 0, breakdown: [] }; return `<main class="results-screen app-shell">${topbar(true)}<section class="results-wrap"><div class="result-status ${r.success ? 'success' : 'failure'}"><span>${r.success ? icon('check') : '!'}</span><p class="kicker">DIVE REPORT · ${maps[state.mapId - 1]?.name.toUpperCase() || 'TRAINING LAGOON'}</p><h1>${r.success ? 'Mission complete.' : 'Dive ended.'}</h1><p>${r.success ? 'You returned safely. Your field data is now banked.' : 'Collected rewards are saved. Visit the shop to upgrade.'}</p></div><div class="result-grid"><div><span>MARKERS</span><strong>${r.markers}</strong></div><div><span>DEEPEST POINT</span><strong>${Math.round(r.depth)}m</strong></div><div><span>POINTS BANKED</span><strong>${r.points}</strong></div></div><div class="reward-panel"><div class="section-head"><div><p class="kicker">REWARD BREAKDOWN</p><h2>${r.success ? 'Good choices add up.' : 'Rewards saved.'}</h2></div><span class="total-points">+${r.points} pts</span></div>${r.breakdown.length ? r.breakdown.map(item => `<div class="reward-row"><span>${item.label}</span><strong>+${item.points}</strong></div>`).join('') : '<p class="muted">Complete the objective and reach the buoy to bank your provisional points.</p>'}</div><div class="result-actions"><button class="primary-btn" data-action="dock">RETURN TO DOCK <span>→</span></button><button class="secondary-btn" data-action="home">MAIN MENU</button></div></section>${overlay()}</main>`; }
function overlay() { if (!state.modal) return ''; if (state.modal === 'how-to') return `<div class="modal-backdrop"><section class="modal-card"><button class="modal-close" data-action="close-modal" aria-label="Close">×</button><p class="kicker">FIELD GUIDE</p><h2>How to play</h2><div class="guide-list"><p><b>1</b><span>Swim with WASD or arrow keys. Hold Shift to sprint, but watch stamina and oxygen.</span></p><p><b>2</b><span>Move close to a glowing marker, and it is collected automatically.</span></p><p><b>3</b><span>When all three markers are recovered, choose Done to bank rewards or stay to explore.</span></p><p><b>4</b><span>Press Escape to pause. Surface early only if you are ready to lose provisional rewards.</span></p></div><button class="primary-btn" data-action="close-modal">GOT IT <span>→</span></button></section></div>`; if (state.modal === 'settings') return `<div class="modal-backdrop"><section class="modal-card"><button class="modal-close" data-action="close-modal" aria-label="Close">×</button><p class="kicker">PREFERENCES</p><h2>Settings</h2><div class="settings-list"><label><span>Sound effects</span><input type="checkbox" data-setting="soundEnabled" ${save.settings.soundEnabled ? 'checked' : ''}></label><label><span>Reduced motion</span><input type="checkbox" data-setting="reducedMotion" ${save.settings.reducedMotion ? 'checked' : ''}></label></div><button class="primary-btn" data-action="close-modal">DONE <span>→</span></button></section></div>`; if (state.modal === 'new-game') return `<div class="modal-backdrop"><section class="modal-card"><p class="kicker">ABANDON DIVE</p><h2>Leave the water?</h2><p class="muted">Your provisional points will be lost, but saved equipment and currency remain safe.</p><div class="modal-actions"><button class="secondary-btn" data-action="close-modal">KEEP DIVING</button><button class="danger-btn" data-action="confirm-abort">ABANDON DIVE</button></div></section></div>`; if (state.modal === 'reset-save') return `<div class="modal-backdrop"><section class="modal-card"><p class="kicker">RESET PROGRESS</p><h2>Start a new expedition?</h2><p class="muted">This clears saved points, equipment, and map progress from this browser.</p><div class="modal-actions"><button class="secondary-btn" data-action="close-modal">CANCEL</button><button class="danger-btn" data-action="reset-save">RESET SAVE</button></div></section></div>`; return `<div class="modal-backdrop"><section class="modal-card shop-modal"><button class="modal-close" data-action="close-modal" aria-label="Close">×</button><p class="kicker">EQUIPMENT BAY</p><h2>Shop and equip</h2><p class="muted">Spendable points: <strong class="accent-text">${save.spendablePoints.toLocaleString()}</strong></p><div class="shop-grid">${Object.entries(equipment).filter(([,item]) => item.price > 0).map(([id,item]) => { const owned = save.ownedEquipment.includes(id); const isEquipped = save.equipped[item.slot] === id; return `<article class="shop-item ${owned ? 'owned' : ''}"><div><span class="item-slot">${item.slot.toUpperCase()}</span><h3>${item.name}</h3><p>${item.detail}</p></div><div class="shop-item-foot"><strong>${owned ? 'OWNED' : `${item.price} pts`}</strong><button class="small-btn" data-action="${owned ? 'equip' : 'buy'}" data-item="${id}" ${isEquipped ? 'disabled' : ''}>${isEquipped ? 'EQUIPPED' : owned ? 'EQUIP' : 'BUY'}</button></div></article>`; }).join('')}</div></section></div>`; }

function setToast(message) { state.toast = message; const el = document.querySelector('#toast'); if (el) { el.textContent = message; el.classList.add('visible'); clearTimeout(setToast.timer); setToast.timer = setTimeout(() => el.classList.remove('visible'), 3200); } }
function render() { const root = document.querySelector('#app'); const liveCanvas = state.screen === 'dive' && scene3d?.renderer.domElement; root.innerHTML = state.screen === 'menu' ? menu() : state.screen === 'dock' ? dock() : state.screen === 'dive' ? dive() : results(); if (liveCanvas) { document.querySelector('#scene')?.replaceWith(liveCanvas); resizeScene(); } bind(); }
function goDock() { state.screen = 'dock'; state.modal = null; state.result = null; render(); }
function startDive(mapId = state.mapId) { const map = maps.find(m => m.id === Number(mapId)); if (!map || !isUnlocked(map)) return; state = { ...state, screen: 'dive', modal: null, mapId: map.id, running: true, paused: false, oxygen: 100, stamina: 100, fatigue: 0, health: 100, heart: 76, depth: 4, provisional: 0, markers: 0, time: 0, keys: {}, last: performance.now(), sprintLocked: false, checkpoints: new Set(), result: null, toast: '', explorationPoints: 0 }; render(); setupScene(); requestAnimationFrame(loop); }
function finishDive(success, reason = '') { if(!state.running)return;state.running=false;state.paused=false;state.modal=null;if(scene3d){window.removeEventListener('resize',resizeScene);scene3d.renderer.dispose();scene3d=null;}state.result={success:false,reason,markers:state.markers,depth:state.depth,points:state.explorationPoints||0,breakdown:[{label:'Discoveries saved to wallet',points:state.explorationPoints||0}]};state.screen='results';render();}
function trySurface() { if (!scene3d) return; const d = scene3d.player.position.distanceTo(scene3d.buoy.position); if (d > 1.1) { setToast('Follow the direction marker to reach the surface buoy.'); return; } if (state.markers < 3) { setToast('Recover all three markers before surfacing.'); return; } finishDive(true); }
function abortDive() { state.modal = 'new-game'; render(); }
function bind() { document.querySelectorAll('[data-action]').forEach(el => el.addEventListener('click', () => { const action = el.dataset.action; if (action === 'continue') { state.screen = 'dock'; render(); } else if (action === 'new-game') { state.modal = 'reset-save'; render(); } else if (action === 'settings') { state.modal = 'settings'; render(); } else if (action === 'how-to') { state.modal = 'how-to'; render(); } else if (action === 'open-shop') { state.modal = 'shop'; render(); } else if (action === 'toggle-pause') togglePause(); else if (action === 'camera') setToast('Camera view locked to side-on field mode.'); else if (action === 'close-modal') { const wasDive = state.screen === 'dive'; state.modal = null; render(); if (wasDive && state.running) { state.last = performance.now(); requestAnimationFrame(loop); } } else if (action === 'home') { if (state.running) return; state.screen = 'menu'; render(); } else if (action === 'dock' || action === 'back') goDock(); else if (action === 'start') startDive(); else if (action === 'surface') trySurface(); else if (action === 'resume') { state.paused = false; state.last = performance.now(); render(); requestAnimationFrame(loop); } else if (action === 'abort') abortDive(); else if (action === 'confirm-abort') finishDive(false, 'abandoned'); else if (action === 'reset-save') { localStorage.removeItem(STORAGE_KEY); Object.assign(save, cloneDefault()); state.modal = null; state.screen = 'menu'; render(); } else if (action === 'buy' || action === 'equip') handleEquipment(action, el.dataset.item); })); document.querySelectorAll('[data-move]').forEach(el => { const key = { up: 'ArrowUp', down: 'ArrowDown', swim: 'ArrowRight' }[el.dataset.move]; el.style.touchAction = 'none'; el.addEventListener('pointerdown', event => { event.preventDefault(); el.setPointerCapture(event.pointerId); state.keys[key] = true; }); for (const type of ['pointerup', 'pointercancel', 'lostpointercapture']) el.addEventListener(type, () => { state.keys[key] = false; }); }); document.querySelectorAll('[data-setting]').forEach(el => el.addEventListener('change', () => { save.settings[el.dataset.setting] = el.checked; persist(); })); document.querySelectorAll('[data-map]').forEach(el => el.addEventListener('click', () => { state.mapId = Number(el.dataset.map); render(); })); }
function handleEquipment(action, id) { const item = equipment[id]; if (!item) return; if (action === 'buy') { if (save.spendablePoints < item.price) { setToast('Not enough points for this equipment.'); return; } save.spendablePoints -= item.price; save.ownedEquipment.push(id); } save.equipped[item.slot] = id; persist(); state.modal = null; render(); }

function setupScene() { const canvas = document.querySelector('#scene'); const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false }); renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.75)); renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.12; renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap; const scene = new THREE.Scene(); scene.background = new THREE.Color(0x176a79); scene.fog = new THREE.Fog(0x176a79, 18, 52); const camera = new THREE.PerspectiveCamera(58, 1, .1, 130); camera.position.set(0, 1.4, 18); camera.lookAt(0, .2, 0); scene.add(new THREE.HemisphereLight(0xb9f3ed, 0x061b25, 1.8)); const light = new THREE.DirectionalLight(0xfff0c2, 3.2); light.position.set(-8, 12, 10); light.castShadow = true; scene.add(light); const seabed = new THREE.Mesh(new THREE.BoxGeometry(44, .7, 5), new THREE.MeshStandardMaterial({ color: 0x254d4b, roughness: 1 })); seabed.receiveShadow = true; seabed.position.set(0, -3.25, 0); scene.add(seabed); for (let i = 0; i < 19; i++) { const coral = makeCoral([0xd27878, 0xd4a365, 0x8e7bd2][i % 3]); coral.position.set(-21 + i * 2.3, -2.9, -1 + (i % 3) * .5); coral.scale.setScalar(.55 + Math.random() * .65); scene.add(coral); } const fish = []; for (let i = 0; i < 18; i++) { const f = makeFish([0xf1c96c, 0x84dcd8, 0xef8d90][i % 3]); f.position.set(-20 + Math.random() * 40, -.8 + Math.random() * 4, -1 + Math.random() * 2); scene.add(f); fish.push(f); } const marineLife = []; const sharks = []; const player = new THREE.Group(); player.position.set(-3.5, 2.1, 1); scene.add(player); loadDiverModel(player); const bubbles = makeBubbleEmitter(scene); const particles = makeWaterParticles(scene); const rocks = makeRocks(scene); const markerPositions = [[-8, .2], [0, -4.2], [9, -8.8]]; const markerMat = new THREE.MeshStandardMaterial({ color: 0xb8f36b, emissive: 0x4f9b52, emissiveIntensity: 2.5 }); const markers = markerPositions.map(([x, y], index) => { const mesh = new THREE.Mesh(new THREE.OctahedronGeometry(.3), markerMat); mesh.position.set(x, y, 0); scene.add(mesh); return { id: index + 1, mesh, x, y, collected: false }; }); const buoy = new THREE.Mesh(new THREE.SphereGeometry(.34, 16, 12), new THREE.MeshStandardMaterial({ color: 0xffb86b, emissive: 0x814c2e, emissiveIntensity: 1.5 })); buoy.position.set(18, 4.5, 0); scene.add(buoy); const surface = makeSurface(scene); scene3d = { renderer, scene, camera, player, buoy, markers, fish, marineLife, sharks, bubbles, particles, rocks, surface, mapBounds: { min: -20, max: 20 } }; resizeScene(); window.addEventListener('resize', resizeScene); animateScene(); }
